// TH15 v1.00b Stage 7 Extra Boss6 (nonspell 6).
// Source: st07bs.ecl.txt:804-867, helpers 869-902 (Boss6_at) and 904-949 (Boss6_at2).
// Entry-state boxes/position from st07bs.ecl.txt:8-39. Timer base st07bs.ecl.txt:822;
// source timeout 4200 (st07bs.ecl.txt:843). Rank 4 only (Extra).

const TIME_LIMIT: int = 4324;   // 120 opening buffer + 4200 source window + 4 startup margin
const OPENING_BUFFER: int = 120;

const BOSS_HP: int = 20500;     // st07bs.ecl.txt:807 lifeSet(20500)
const KNIFE_COLOR: int = 6;     // etSprite(...,9,6)

// st07bs.ecl.txt:851 moveLimit(0,128,280,64): center (0,128), full width/height.
const LIMIT_X: fx = 140fx;
const LIMIT_Y_LO: fx = 96fx;
const LIMIT_Y_HI: fx = 160fx;
const INNER_X: fx = 70fx;
const INNER_Y_LO: fx = 112fx;
const INNER_Y_HI: fx = 144fx;

// Boss6_at: mode10, N=25, M=2. The two layers are two full rings rotated by
// +/- delta/2; source delta 0.022689281 rad (half = 118 BAM) and 0.027925268
// rad (half = 146 BAM). Speed is uniform per wave (2 then 4), so one ring per
// layer is the same point set. Source waves 5 frames apart; A steps +1deg then
// -1deg per wave.
async sub boss6_at() {
    sh_reset(0);
    sh_sprite(0, TH15_KUNAI, KNIFE_COLOR);
    sh_ring(0, 1);
    sh_count(0, 25, 1);
    sh_aim(0, 0);
    // etDist(0,24) and ANIM a=1 (position -= 4*velocity): net spawn distance.
    sh_dist(0, 16fx);
    var a: int = rand(65536) - 32768;   // %A = %RANDRAD
    for g1 in 0..10 {                    // $B = 10, wait(5) per wave
        sh_speed(0, 2fx, 0fx);
        sh_angle(0, (a + 118) as angle, 0deg);
        sh_fire(0);
        sh_angle(0, (a - 118) as angle, 0deg);
        sh_fire(0);
        a = a + 182;                    // 0.017453f
        wait(5);
    }
    sh_dist(0, 8fx);                    // speed 4: 24 - 4*4
    for g2 in 0..10 {                    // $C = 10
        sh_speed(0, 4fx, 0fx);
        sh_angle(0, (a + 146) as angle, 0deg);
        sh_fire(0);
        sh_angle(0, (a - 146) as angle, 0deg);
        sh_fire(0);
        a = a - 182;
        wait(5);
    }
}

// Boss6_at2: mode10, N=10, M=2, uniform speed 1. Source delta 0.017453292 rad
// (half = 91 BAM); A steps -6deg then +6deg then +6deg per wave, with -1deg
// between groups. Source etDist(0,24) targets emitter 0, so emitter 1 keeps
// dist 0; ANIM a=1 then gives the net -4*1 spawn displacement.
async sub boss6_at2() {
    sh_reset(1);
    sh_sprite(1, TH15_KUNAI, KNIFE_COLOR);
    sh_ring(1, 1);
    sh_count(1, 10, 1);
    sh_aim(1, 0);
    sh_dist(1, -4fx);
    var a: int = rand(65536) - 32768;
    for c1 in 0..10 {
        sh_speed(1, 1fx, 0fx);
        sh_angle(1, (a + 91) as angle, 0deg);
        sh_fire(1);
        sh_angle(1, (a - 91) as angle, 0deg);
        sh_fire(1);
        a = a - 1092;                   // 0.10472f
        wait(5);
    }
    a = a - 182;                        // 0.017453f
    for c2 in 0..10 {
        sh_speed(1, 1fx, 0fx);
        sh_angle(1, (a + 91) as angle, 0deg);
        sh_fire(1);
        sh_angle(1, (a - 91) as angle, 0deg);
        sh_fire(1);
        a = a + 1092;
        wait(5);
    }
    a = a - 182;
    for c3 in 0..10 {
        sh_speed(1, 1fx, 0fx);
        sh_angle(1, (a + 91) as angle, 0deg);
        sh_fire(1);
        sh_angle(1, (a - 91) as angle, 0deg);
        sh_fire(1);
        a = a + 1092;
        wait(5);
    }
}

// moveRand(60,4,1.9) reuses the verified TH16/TH18 fixed-direction recipe:
// one signed random angle per call (plus the central WORD), linear 1.9->0
// speed, per-frame clamp inside moveLimit. int slot 0 = next step, fx 0/1 =
// logical unit vector. ECL reads the position armed by the previous frame, so
// the pre-armed next step matches the source fire-position sequence.
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 1.9fx * ((60 - k) as fx) / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -LIMIT_X { nx = -LIMIT_X; }
    if nx > LIMIT_X { nx = LIMIT_X; }
    if ny < LIMIT_Y_LO { ny = LIMIT_Y_LO; }
    if ny > LIMIT_Y_HI { ny = LIMIT_Y_HI; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_step();
}

sub move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -INNER_X {
        a = r / 3;
    } else if $self_x > INNER_X {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < INNER_Y_LO {
        if a < 0 { a = -a; }
    } else if $self_y > INNER_Y_HI {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_angle(a as angle);
}

sub move_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

async sub boss() {
    var t: int = 0;                    // source frames since timerReset
    set_invuln(65535);                 // invincible shell; source setInvuln(120) subsumed
    set_hitbox(24fx);                  // setHitbox(48,48): first*0.5
    set_hurtbox(20fx);                 // setHurtbox(40,40): first*0.5
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);  // movePosTime(60,4,0,128)
    wait(120); t = t + 120;            // st07bs.ecl.txt:847
    wait(60); t = t + 60;              // st07bs.ecl.txt:850
    // st07bs.ecl.txt:851 moveLimit(0,128,280,64) is applied by arm_next_step.
    wait(60); t = t + 60;              // st07bs.ecl.txt:856
    while t < 4200 {                   // st07bs.ecl.txt:843 setInterrupt timeout
        spawn boss6_at();              // st07bs.ecl.txt:859
        spawn boss6_at2();             // st07bs.ecl.txt:860
        wait(100); t = t + 100;        // st07bs.ecl.txt:861
        if t >= 4200 { break; }        // source timeout replaces the Boss6 task
        move_rand();                   // st07bs.ecl.txt:862 moveRand(60,4,1.9)
        var rem: int = 4200 - t;
        if rem > 60 { rem = 60; }
        move_wait(rem);                // st07bs.ecl.txt:863
        t = t + rem;
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, BOSS_HP, 0, 0, 0, boss);  // st07bs.ecl.txt:15 movePos(0,128)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

